def mf_subagent_session_token_hash(session_token: str) -> str:
    token = str(session_token or "").strip()
    if not token:
        return ""
    return "sha256:" + hashlib.sha256(token.encode("utf-8")).hexdigest()


def runtime_context_secret_hash(value: str) -> str:
    token = str(value or "").strip()
    if not token:
        return ""
    return "sha256:" + hashlib.sha256(token.encode("utf-8")).hexdigest()


def runtime_context_fence_token_verifier(
    context: "BranchTaskRuntimeContext",
) -> str:
    """Return the explicit hash-backed verifier for a worker fence.

    New hash-only contexts persist ``fence_token_verifier`` and no raw fence.
    Legacy contexts continue to derive the same verifier from their persisted
    raw fence until an authenticated rotation migrates them.
    """

    stored = str(getattr(context, "fence_token_verifier", "") or "").strip()
    if stored:
        return stored if re.fullmatch(r"sha256:[0-9a-f]{64}", stored) else ""
    return runtime_context_secret_hash(getattr(context, "fence_token", ""))


def runtime_context_has_fence_authority(
    context: "BranchTaskRuntimeContext",
) -> bool:
    return bool(runtime_context_fence_token_verifier(context))


def runtime_context_fence_token_matches(
    context: "BranchTaskRuntimeContext",
    presented_fence_token: str,
) -> bool:
    """Validate a raw fence against the stored verifier.

    Hashes and copy-safe refs are not accepted as bearer credentials: the
    presented value is always hashed before the constant-time comparison.
    """

    presented = str(presented_fence_token or "").strip()
    expected = runtime_context_fence_token_verifier(context)
    actual = runtime_context_secret_hash(presented)
    return bool(
        presented
        and expected
        and actual
        and secrets.compare_digest(expected, actual)
    )


def mf_subagent_session_token_ref(
    *,
    project_id: str,
    runtime_context_id: str,
    task_id: str,
    fence_token_hash: str,
    session_token_hash: str,
    worker_slot_id: str = "",
) -> str:
    """Return a copy-safe bearer ref for a stored mf_sub session token hash."""

    session_hash = str(session_token_hash or "").strip()
    runtime_id = str(runtime_context_id or "").strip()
    task = str(task_id or "").strip()
    fence_hash = str(fence_token_hash or "").strip()
    if not session_hash or not runtime_id or not task or not fence_hash:
        return ""
    seed = "|".join(
        str(value or "").strip()
        for value in (
            "mf_subagent_session_token_ref.v1",
            project_id,
            runtime_id,
            task,
            fence_hash,
            session_hash,
            worker_slot_id,
        )
    )
    return "wstok-" + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:40]


def runtime_context_session_token_ref(
    context: "BranchTaskRuntimeContext",
    *,
    session_token_hash: str = "",
) -> str:
    token_hash = str(session_token_hash or context.session_token_hash or "").strip()
    return mf_subagent_session_token_ref(
        project_id=context.project_id,
        runtime_context_id=runtime_context_id_for_branch_context(context),
        task_id=context.task_id,
        fence_token_hash=runtime_context_fence_token_verifier(context),
        session_token_hash=token_hash,
        worker_slot_id=context.worker_slot_id or context.worker_id,
    )


def runtime_context_session_token_ref_matches(
    context: "BranchTaskRuntimeContext",
    presented_ref: str,
) -> bool:
    expected = runtime_context_session_token_ref(context)
    candidate = str(presented_ref or "").strip()
    return bool(expected and candidate and secrets.compare_digest(expected, candidate))


def issue_mf_subagent_session_token(
    context: "BranchTaskRuntimeContext",
) -> dict[str, Any]:
    """Issue an opaque worker token scoped by the stored runtime context hash."""
    token = secrets.token_urlsafe(32)
    token_hash = mf_subagent_session_token_hash(token)
    fence_verifier = runtime_context_fence_token_verifier(context)
    fence_hash = fence_verifier.removeprefix("sha256:")[:16]
    runtime_context_id = runtime_context_id_for_branch_context(context)
    token_ref = mf_subagent_session_token_ref(
        project_id=context.project_id,
        runtime_context_id=runtime_context_id,
        task_id=context.task_id,
        fence_token_hash=fence_verifier,
        session_token_hash=token_hash,
        worker_slot_id=context.worker_slot_id or context.worker_id,
    )
    return {
        "schema_version": "mf_subagent_same_owner_session_token.v1",
        "issued": True,
        "token_type": "same_owner_scoped",
        "session_token": token,
        "session_token_ref": token_ref,
        "session_token_hash": token_hash,
        "session_token_persisted": False,
        "session_token_ref_persisted": False,
        "scope": {
            "project_id": context.project_id,
            "task_id": context.task_id,
            "runtime_context_id": runtime_context_id,
            "fence_token_hash": fence_hash,
            "agent_id": context.agent_id,
            "allocation_owner": context.allocation_owner or context.agent_id,
            "worker_slot_id": context.worker_slot_id or context.worker_id,
            "backlog_id": context.backlog_id,
        },
        "delivery": "worker_host_envelope",
        "copy_safe_delivery": "runtime_context_session_token_ref",
        "raw_token_persistence": "not_persisted",
    }


def _runtime_context_parse_utc(value: str) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _runtime_context_parse_utc_strict(value: str) -> datetime | None:
    """Parse an explicitly timezone-aware timestamp for auth decisions.

    Persistence and display compatibility still use the permissive parser
    above.  Lease authorization must not reinterpret a naive or malformed
    expiry as UTC, because doing so can turn an invalid persisted lease into
    an apparently active worker session.
    """

    text = str(value or "").strip()
    if not text:
        return None
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        return None
    try:
        return parsed.astimezone(timezone.utc)
    except (OverflowError, ValueError):
        return None


def _runtime_context_now_dt(now_iso: str = "") -> datetime:
    return _runtime_context_parse_utc(now_iso) or datetime.now(timezone.utc)


def _runtime_context_iso(value: datetime) -> str:
    return value.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def runtime_context_session_token_lease_view(
    context: "BranchTaskRuntimeContext",
    *,
    now_iso: str = "",
) -> dict[str, Any]:
    requested_now = str(now_iso or "").strip()
    parsed_now = (
        _runtime_context_parse_utc_strict(requested_now)
        if requested_now
        else datetime.now(timezone.utc)
    )
    clock_valid = parsed_now is not None
    now_dt = parsed_now or datetime.now(timezone.utc)
    lease_id = str(context.lease_id or "").strip()
    lease_expires_at = str(context.lease_expires_at or "").strip()
    canonical_no_lease = not lease_id and not lease_expires_at
    has_lease = bool(lease_id or lease_expires_at)
    expires_dt = _runtime_context_parse_utc_strict(lease_expires_at)
    complete_lease_record = bool(lease_id and lease_expires_at)
    lease_record_valid = bool(
        canonical_no_lease
        or (complete_lease_record and expires_dt is not None)
    )
    remaining: int | None = None
    if expires_dt is not None and clock_valid:
        remaining = int((expires_dt - now_dt).total_seconds())
    invalid = not clock_valid or not lease_record_valid
    expired = bool(invalid or (remaining is not None and remaining <= 0))
    if invalid:
        status = "invalid"
    elif canonical_no_lease:
        status = "no_lease_recorded"
    elif expired:
        status = "expired"
    else:
        status = "active"
    authorization_valid = bool(
        clock_valid
        and (
            canonical_no_lease
            or (lease_record_valid and status == "active")
        )
    )
    invalid_reason = ""
    if not clock_valid:
        invalid_reason = "invalid_authorization_clock"
    elif has_lease and not complete_lease_record:
        invalid_reason = "incomplete_lease_record"
    elif complete_lease_record and expires_dt is None:
        invalid_reason = "invalid_lease_expiry"
    renewal_supported = bool(
        context.status in ACTIVE_MF_SUBAGENT_GRAPH_QUERY_STATES
        and context.session_token_hash
        and runtime_context_has_fence_authority(context)
    )
    return {
        "schema_version": "mf_subagent_runtime_session_token_lease.v1",
        "has_lease": has_lease,
        "lease_id": lease_id,
        "lease_expires_at": lease_expires_at,
        "lease_remaining_ttl_seconds": (
            max(0, remaining) if remaining is not None else None
        ),
        "expired": expired,
        "status": status,
        "authorization_valid": authorization_valid,
        "canonical_no_lease": canonical_no_lease,
        "lease_record_valid": lease_record_valid,
        "expiry_valid": expires_dt is not None,
        "clock_valid": clock_valid,
        "invalid_reason": invalid_reason,
        "renewal_supported": renewal_supported,
        "renewal_max_ttl_seconds": MF_SUBAGENT_SESSION_REISSUE_MAX_TTL_SECONDS,
        "renewal_default_ttl_seconds": MF_SUBAGENT_SESSION_REISSUE_DEFAULT_TTL_SECONDS,
        "renewal_endpoint": (
            "/api/graph-governance/{project_id}/runtime-contexts/"
            "{runtime_context_id}/session-token/reissue"
        ),
        "session_token_ref": runtime_context_session_token_ref(context),
        "session_token_ref_available": bool(runtime_context_session_token_ref(context)),
        "raw_session_token_exposed": False,
        "raw_session_token_persisted": False,
        "now": _runtime_context_iso(now_dt),
    }


def _runtime_session_token_expired_error(
    context: "BranchTaskRuntimeContext",
    *,
    runtime_context_id: str = "",
    now_iso: str = "",
) -> BranchRuntimeFenceError:
    runtime_id = runtime_context_id or runtime_context_id_for_branch_context(context)
    lease = runtime_context_session_token_lease_view(context, now_iso=now_iso)
    return _graph_query_fence_error(
        "runtime_session_token_expired",
        details={
            "runtime_context_id": runtime_id,
            "task_id": context.task_id,
            "parent_task_id": _parent_task_id_for_context(context),
            "reason": "runtime_session_token_expired",
            "session_token_lease": lease,
            "renewal": {
                "schema_version": "mf_subagent_session_token_reissue_hint.v1",
                "available": bool(lease.get("renewal_supported")),
                "method": "POST",
                "path": (
                    "/api/graph-governance/{project_id}/runtime-contexts/"
                    "{runtime_context_id}/session-token/reissue"
                ),
                "required_body_fields": [
                    "runtime_context_id",
                    "task_id",
                    "parent_task_id",
                    "fence_token",
                    "session_token",
                    "target_project_root",
                ],
                "max_ttl_seconds": MF_SUBAGENT_SESSION_REISSUE_MAX_TTL_SECONDS,
                "raw_session_token_persisted": False,
                "fail_closed_for": [
                    "stale_context",
                    "closed_context",
                    "scope_mismatch",
                    "wrong_fence",
                    "wrong_session_token",
                ],
            },
        },
    )


def _bounded_reissue_ttl_seconds(value: Any) -> int:
    try:
        requested = int(value)
    except (TypeError, ValueError):
        requested = MF_SUBAGENT_SESSION_REISSUE_DEFAULT_TTL_SECONDS
    return max(
        MF_SUBAGENT_SESSION_REISSUE_MIN_TTL_SECONDS,
        min(requested, MF_SUBAGENT_SESSION_REISSUE_MAX_TTL_SECONDS),
    )


class BranchRuntimeFenceError(ValueError):
    """Raised when a stale worker attempts to mutate branch runtime state.

    ``details`` carries the public/secret-safe correction for the HTTP surface.
    It is always a mapping so a handler never has to guess the shape, and it
    never contains a raw fence/session/route credential.
    """

    def __init__(self, message: str, details: Mapping[str, Any] | None = None):
        super().__init__(message)
        self.details: dict[str, Any] = dict(details or {})


class MergeQueueItemNotFoundError(KeyError):
    """Raised when a merge queue selector matches no durable queue item.

    Subclasses ``KeyError`` so existing ``except KeyError`` callers keep their
    behaviour, while HTTP handlers can name the requested selector and the
    visible durable set instead of returning a bare 500.
    """

    def __init__(self, message: str, details: Mapping[str, Any] | None = None):
        super().__init__(message)
        self.message = message
        self.details: dict[str, Any] = dict(details or {})


class IntegrationEpochFrozenError(ValueError):
    """Raised when an open batch epoch rejects an unrelated target mutation."""

    def __init__(self, message: str, epoch: "IntegrationEpoch"):
        super().__init__(message)
        self.epoch = epoch


class IntegrationEpochUnlandableChildReleaseError(ValueError):
    """Fail-closed refusal for the explicit incomplete-fan-in action."""

    def __init__(self, error: str, message: str, **details: Any):
        super().__init__(message)
        self.error = str(error or "integration_epoch_release_refused")
        self.message = message
        self.details: dict[str, Any] = {
            "error": self.error,
            "message": message,
            "release_performed": False,
            "merge_credit_granted": False,
            "zero_write_rejection": True,
            **details,
        }


class IntegrationEpochWorldRefSealError(ValueError):
    """Fail-closed refusal for the typed epoch WorldRef seal action."""

    def __init__(self, error: str, message: str, **details: Any):
        super().__init__(message)
        self.error = str(error or "integration_epoch_worldref_seal_refused")
        self.message = message
        self.details: dict[str, Any] = {
            "error": self.error,
            "message": message,
            "seal_performed": False,
            "writes_performed": False,
            "mutation_performed": False,
            "zero_write_rejection": True,
            "merge_credit_granted": False,
            "target_head_mutated": False,
            "pass_synthesized": False,
            "resume_authorized": False,
            "reconcile_authorized": False,
            "release_authorized": False,
            **details,
        }


